"use client";

import { cx } from "@/utils/cx";

const STYLES = [
  {
    label: "Title 1 · Medium",
    className: "text-title-1-medium",
    sample: "Make room for good ideas.",
  },
  {
    label: "Title 2 · Medium",
    className: "text-title-2-medium",
    sample: "A clear view of your work",
  },
  {
    label: "Headline · Medium",
    className: "text-headline-medium",
    sample: "Everything in its place",
  },
  {
    label: "Body · Regular",
    className: "text-body-regular",
    sample: "Thoughtful type makes a busy interface easier to read.",
  },
  {
    label: "Body 2 · Medium",
    className: "text-body-2-medium",
    sample: "Last updated a few moments ago",
  },
  {
    label: "Caption 1 · Medium",
    className: "text-caption-1-medium",
    sample: "HELPFUL DETAILS, QUIETLY PRESENT",
  },
];

export default function TypographyDemo() {
  return (
    <div className="w-full max-w-xl overflow-hidden rounded-3xl border border-border-button-default bg-background-primary-default">
      {STYLES.map((style) => (
        <div
          key={style.className}
          className="flex flex-col gap-2 border-b border-separator-border px-5 py-4 last:border-0"
        >
          <span className="text-caption-1-medium text-text-tertiary">{style.label}</span>
          <p className={cx(style.className, "text-text-primary")}>{style.sample}</p>
        </div>
      ))}
    </div>
  );
}

